def compute(vars):
    values = [vars["v1"], vars["v2"]]
    years_exceeding = sum(1 for value in values if value > 3)
    return {
        "value": years_exceeding,
        "trace": {
            "values": values,
            "threshold": 3,
            "years_exceeding_threshold": years_exceeding,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "years"
            }
        }
    }
